export function getAllDissertationText(): string {
  return DISSERTATION_FULL_QUESTIONS.map(q => q.text).join('\n\n' + '='.repeat(40) + '\n\n');
}

export function getScenarioQuestions(scenarioId: string): DissertationQuestion[] {
  return DISSERTATION_FULL_QUESTIONS.filter(q => q.scenarioId === scenarioId);
}
